mapper.select:
SELECT 
FROM resume
WHERE user_id = #{owner,typeHandler=com.resumecraft.common.UuidTypeHandler}
    AND deleted = false

    AND POSITION(LOWER(#{filter}) IN LOWER(title)) > 0

ORDER BY updated_at DESC, id ASC
LIMIT #{limit}
OFFSET #{pageOffset}

